<script setup lang="ts">
import type { ComparisonType, VariantKey } from '~/types/comparisons'
import { comparisonStatus, comparisonText, comparisonTypes, comparisonsTestBackend } from '~/utils/comparisons'
import { createComparisonsController } from '~/utils/comparisons-controller'
import { displayDate } from '~/utils/provenance'

definePageMeta({ access: { tenant: true } })
useHead({ title: 'Сравнение сценариев · Школьные события' })
const api = useComparisonsApi(), route = useRoute(), config = useRuntimeConfig()
const testBackend = comparisonsTestBackend(config.public.apiOrigin)
const c = createComparisonsController({ request: (...args) => api.forContext().request(...args), list: (...args) => api.forContext().list(...args), show: (...args) => api.forContext().show(...args), variants: (...args) => api.forContext().variants(...args), create: (...args) => api.forContext().create(...args), select: (...args) => api.forContext().select(...args) }, api.context)
const { history, comparison, variantData, request, pending, error, confirmation, uncertain } = c
const requestId = ref(''), type = ref<ComparisonType>('universal_vs_personalized'), selected = ref<VariantKey>('A')
const canMutate = computed(() => ['teacher', 'school_admin'].includes(api.context().role))
const typeOptions = Object.entries(comparisonTypes).map(([value, label]) => ({ value, label }))
const differences = computed(() => comparison.value ? Object.entries(comparison.value.differences_summary).filter(([, value]) => value && typeof value === 'object' && !Array.isArray(value) && 'variant_a' in value && 'variant_b' in value) : [])
const differenceLabels: Record<string, string> = { pedagogical_approach: 'Педагогический подход', resource_adaptation: 'Ресурсы и оснащение', roles_differentiation: 'Роли участников', age_customization: 'Возрастная адаптация', regional_component: 'Региональный компонент' }
watch(() => [JSON.stringify(api.context()), route.query.request], async () => { c.reset(); requestId.value = typeof route.query.request === 'string' ? route.query.request : ''; selected.value = 'A'; await c.refresh(); if (requestId.value) await c.loadRequest(requestId.value) }, { immediate: true, flush: 'sync' })
watch(requestId, () => { request.value = null })
let pollTimer: ReturnType<typeof setInterval> | undefined
onMounted(() => { pollTimer = setInterval(() => { if (comparison.value?.status === 'pending' && !pending.value && !error.value) void c.reconcile() }, 3000) })
onBeforeUnmount(() => { if (pollTimer) clearInterval(pollTimer); c.reset() })
function choose(key: VariantKey) { selected.value = key; document.getElementById('comparison-selection')?.scrollIntoView({ behavior: 'smooth', block: 'start' }) }
</script>
<template>
  <div class="comparisons-page fe010 fe010-page">
    <header class="fe010-heading"><p class="fe010-eyebrow">Сравнение / {{ comparison ? comparisonTypes[comparison.comparison_type] : 'A/B-сценарии' }}</p><h1>{{ comparison?.comparison_type === 'cultural_context' ? 'Культурная часть без стереотипов' : 'Один повод — два разных сценария' }}</h1><p>Сравните сохранённые документы и выберите подходящий вариант для своих условий.</p></header>
    <UiAlert v-if="testBackend" tone="warning">Изолированный тестовый контур localhost:8001. Новые сравнения автоматически помечаются как синтетические.</UiAlert>
    <UiAlert v-if="error" tone="error">{{ error.message }}<UiButton variant="secondary" :disabled="!!pending" @click="c.reconcile">Повторить чтение</UiButton></UiAlert>
    <section class="ui-card comparison-create"><h2>Создать сравнение</h2><p>Укажите ID уже сохранённого запроса текущей школы или перейдите сюда из сохранённого запроса.</p><form class="comparison-form" @submit.prevent="c.loadRequest(requestId.trim())"><UiField v-model="requestId" label="ID запроса сценария" autocomplete="off" :disabled="!!pending" required /><UiButton type="submit" variant="secondary" :loading="pending === 'request'" :disabled="!!pending">Загрузить запрос</UiButton></form><template v-if="request"><ScenarioRequestDetails :request="request" /><div class="comparison-form"><UiSelect v-model="type" label="Что сравниваем" :options="typeOptions" :disabled="!!pending" /><UiButton :loading="pending === 'create'" :disabled="!!pending || !!uncertain || !canMutate" @click="c.create(request.id, type)">Создать пару сценариев</UiButton></div></template><p v-if="!canMutate" class="muted">Для создания и выбора требуется школьная роль педагога или администратора.</p><UiAlert v-if="uncertain === 'create'" tone="warning">Результат создания неизвестен. История перечитывается через GET; API не возвращает исходный request_id в истории, поэтому автоматически определить созданную пару нельзя. Сверьте историю перед новым созданием.<div class="comparison-actions"><UiButton variant="secondary" :disabled="!!pending" @click="c.refresh">Перечитать историю</UiButton><UiButton v-if="history.length" variant="secondary" :disabled="!!pending" @click="c.acknowledgeNewCreate">Историю проверил — разрешить новое создание</UiButton></div></UiAlert></section>
    <UiState v-if="pending === 'comparison' || pending === 'create'" kind="loading" title="Подготавливаем сравнение" description="Получаем фактическое состояние и сохранённые варианты A/B." />
    <template v-if="comparison"><div class="row comparison-state-heading"><h2>Варианты одного события</h2><UiBadge>{{ comparisonStatus(comparison.status) }}</UiBadge><UiBadge v-if="comparison.is_synthetic">Синтетические данные</UiBadge><UiButton variant="secondary" :disabled="!!pending" @click="c.show(comparison.id)">Обновить пару</UiButton></div><UiState v-if="comparison.status === 'pending'" kind="loading" title="Модель готовит два варианта" description="Сравнение выполняется в очереди. Статус обновляется автоматически; повторно создавать пару не нужно." /><UiState v-else-if="comparison.status === 'failed'" kind="error" title="Сравнение не создано" description="Не удалось подготовить два проверенных варианта. Платные запросы автоматически не повторяются. Можно создать новую пару из сохранённого запроса." /><template v-else><ScenarioQualityNotice :review="comparison.quality_review?.B" /><div class="comparison-grid"><ComparisonVariantCard v-for="variant in variantData?.variants ?? comparison.variants" :key="`${comparison.id}:${variant.variant_key}`" :variant="variant" :type="comparison.comparison_type" :selected="comparison.selected_variant === variant.variant_key" :selectable="canMutate && comparison.status === 'completed' && !comparison.selected_variant && !uncertain" :pending="!!pending" @choose="choose(variant.variant_key)" /></div></template><section v-if="differences.length" class="comparison-differences ui-card"><h2>Педагогические отличия сохранённой пары</h2><UiAlert v-if="comparison.comparison_type === 'cultural_context' && !comparison.is_cultural_available" tone="warning">Описание B относится к сохранённому снимку. Сейчас сервер не допускает этот вариант; выбрать его нельзя. Перепроверьте актуальные доказательства.</UiAlert><dl><template v-for="[key, value] in differences" :key="key"><dt>{{ differenceLabels[key] ?? key }}</dt><dd v-if="value && typeof value === 'object' && !Array.isArray(value)"><p><strong>A:</strong> {{ comparisonText(value.variant_a) }}</p><p><strong>B:</strong> {{ comparisonText(value.variant_b) }}</p></dd></template></dl></section><UiAlert tone="warning">Каждый конкретный культурный факт требует проверки источника. Доступность варианта и выбор педагога не подтверждают достоверность культурных утверждений.</UiAlert><ComparisonSelection v-if="canMutate || comparison.selected_variant" id="comparison-selection" v-model:selected="selected" :comparison="comparison" :pending="!!pending" :confirmation="confirmation" :uncertain="uncertain === 'selection'" @prepare="c.prepare" @confirm="c.confirm" @cancel="confirmation = null" @reconcile="c.reconcile" /></template>
    <section class="comparison-history"><div class="row"><h2>История сравнений</h2><UiButton variant="secondary" :disabled="!!pending" @click="c.refresh">Обновить историю</UiButton></div><UiState v-if="pending === 'history'" kind="loading" title="Загружаем историю" /><UiState v-else-if="!history.length && !error" kind="empty" title="Сравнений пока нет" description="Создайте пару из сохранённого запроса сценария." /><ul v-else class="comparison-history__list"><li v-for="item in history" :key="item.id" class="ui-card"><h3>{{ comparisonTypes[item.comparison_type] }}</h3><p>{{ displayDate(item.created_at) }} · {{ comparisonStatus(item.status) }}</p><p>{{ item.selected_variant ? `Выбран вариант ${item.selected_variant}` : 'Выбор ещё не зафиксирован' }}</p><p v-if="item.selection_reason">{{ item.selection_reason }}</p><p class="muted">{{ item.id }}</p><UiButton variant="secondary" :disabled="!!pending" @click="c.show(item.id)">Открыть сравнение</UiButton></li></ul></section>
  </div>
</template>
